const EXACT={load_must_be_positive:'Enter a load greater than 0 watts.',loads_required:'Add at least one appliance.',bank_voltage_not_multiple_of_battery:'The bank voltage must be a whole multiple of the battery voltage (for example 24 V = 2 × 12 V).',cable_far_too_small_for_load:'This cable is far too thin for this load and length. Use a thicker cable and confirm with a licensed electrician.',city_unknown:'We do not have sun data for this city yet. Pick the nearest city or enter the yield yourself.',inverter_ac_must_use_less:'The inverter AC must use less power than the non-inverter AC for a payback to exist.',inverter_ac_no_payback:'At these figures the saving is too small to pay back the extra price within the working life of an air conditioner. Check the hours a year, the tariff and both power figures.',n_parallel_must_be_whole:'Number of parallel strings must be a whole number.',n_series_must_be_whole:'Number of batteries in series must be a whole number.',range_invalid:'The low end of the price range must be below the high end.',solar_covers_load:'Your solar covers the whole daily load even on a cloudy day, so the battery does not run down.',tariff_data_missing:'Tariff data could not be loaded. Please refresh the page.',calculator_failed:'The calculator could not start. Please refresh the page.',tou_required_at_5kw:'Connections of 5 kW or more are billed on a Time-of-Use (peak/off-peak) meter. Use the ToU bill option.',type_invalid:'Choose MPPT or PWM.',usage_required:'Enter your monthly units or daily kWh.',yield_or_city_or_psh_required:'Pick a city or enter peak sun hours.',ac_protected_lost:'With the AC your monthly total goes over the protected limit, so this bill and the bills of the following six months are charged at unprotected rates. Fewer AC hours may keep you protected.',ac_above_sanctioned:'This AC alone is above your sanctioned load: apply for a higher one before installing it.',protected_max_200_units:'Protected tariff applies only up to 200 units a month. Above that the unprotected rate applies.',lifeline_max_100_units:'Lifeline tariff applies only up to 100 units a month.',monthly_units_all_zero:'Enter the units of at least one month.',length_invalid:'enter a cable length in metres.',history_needs_6_months:'Enter units for each of the last 6 months.',period_unknown:'We do not have the QTA rate for that quarter. Enter the QTA from your bill.',surge_w_required:'Enter the starting (surge) watts of your load, or leave both surge fields blank.',surge_rating_w_required:'Enter the UPS surge rating from its label, or leave both surge fields blank.',appliance_unknown:'Pick an appliance from the list, or choose Custom and enter its watts.',load_exceeds_ups_rating:'This load is more than the UPS can deliver (VA × power factor). Choose a bigger UPS or reduce the load.',surge_exceeds_ups_rating:'The starting surge is above the UPS surge rating. Choose a bigger UPS or remove the motor load.',other_start_below_run:'Starting watts of the other loads cannot be lower than their running watts.',hours_required:'Enter hours per day for at least one appliance.',cable_data_missing:'Cable data could not be loaded. Please refresh the page.',cable_size_unknown:'Pick a standard cable size.',load_above_standard_breakers:'This load needs more than the largest single-phase MCB. Split it into separate circuits or ask a licensed electrician about a three-phase connection.',load_above_cable_table:'This load is above the largest cable in our table. Split it into separate circuits and consult a licensed electrician.',ambient_out_of_range:'Enter an air temperature around the cable between 10 and 60 °C.',circuits_out_of_range:'Enter how many circuits share the conduit or bundle, from 1 to 20.',run_too_long_for_table:'This run is too long for the cables in our table: the voltage drop would exceed the limit. Shorten the run, split the load or consult a licensed electrician.',solar_above_sanctioned:'Your solar array is larger than your sanctioned load. Net billing allows an array up to the sanctioned kW, so the bill and the setups count only the panels that fit. Apply for a higher sanctioned load or plan fewer panels.',price_low_confidence:'The typical price range for this size rests on a single published price list, so treat it as a rough guide and compare at least two more quotes.',above_standard_sizes:'This is above the largest standard size we list. Split the array or circuit into two, or ask a licensed electrician or engineer; the sizes shown are the calculated minimums.',generator_above_standard_sizes:'This is above the largest generator size we list. Use two generators on separate circuits or a larger industrial set, and ask a licensed electrician; the size shown is the calculated minimum.',price_data_missing:'Price data could not be loaded. Enter the typical price range yourself or refresh the page.',load_above_generator:'This load is more than the generator can deliver (kVA × power factor). Enter a bigger generator or a smaller load.',fuel_data_missing:'Fuel data could not be loaded. Please refresh the page.',panels_must_be_whole:'Number of panels must be a whole number.',forecast_invalid:'The solar forecast could not be read. The typical day is shown instead.',forecast_unavailable:'The live forecast is not available right now, so a typical day is shown. Try again later.',volts_required_dc:'For DC, enter the battery or system voltage; there is no standard DC voltage to assume.',cable_over_current_rating:'This cable is not rated for this current (in conduit), so it is unsafe even if the voltage drop is small. Use a thicker cable; the wire size calculator checks both.',ampacity_not_checked_aluminium:'The current rating of aluminium cable is not checked here, only its voltage drop. Check the current rating in the cable maker\'s datasheet, or ask a licensed electrician.',hours_year_invalid:'Hours a year must be above 0 and at most 8,760.',duty_invalid:'Compressor on-time must be a share from 0 to 1, e.g. 0.8.',soiling_rate_invalid:'Dust loss per day is a share: 0.003 means 0.3% a day. Maximum 0.05.',backup_above_home:'Backup cannot be more than your list\'s running watts or daily units.',internal_non_finite:'These numbers are outside a realistic range. Please check your inputs.',};const row=(m)=>`Appliance ${Number(m[1])+1}: `;const PATTERNS=[[/^history_(\d+)_invalid$/,(m)=>`Month ${m[1]}: enter the units as a number (0 or more).`],[/^load_(\d+)_start_below_run$/,(m)=>`${row(m)}starting watts cannot be lower than running watts.`],[/^load_(\d+)_watts_required$/,(m)=>`${row(m)}enter its watts.`],[/^load_(\d+)_hours_invalid$/,(m)=>`${row(m)}hours per day must be a number from 0 to 24.`],[/^load_(\d+)_start_invalid$/,(m)=>`${row(m)}enter its starting watts as a number (0 or more).`],[/^load_(\d+)_qty_invalid$/,(m)=>`${row(m)}enter how many as a whole number.`],[/^(?:load|appliance)_(\d+)_(?:\w+_)?invalid$/,(m)=>`${row(m)}enter its watts as a number (0 or more).`],[/^(\w+)_required$/,(m,f)=>`Enter ${f(m[1])}.`],[/^(\w+)_invalid$/,(m,f,pick)=>(pick.includes(m[1])?`Choose ${f(m[1])} from the list.`:`${cap(f(m[1]))} must be a number, for example 12 or 1500.`)],[/^(\w+)_must_be_positive$/,(m,f)=>`${cap(f(m[1]))} must be greater than 0.`],[/^(\w+)_too_small$/,(m,f)=>`${cap(f(m[1]))} is too small.`],[/^(\w+)_too_large$/,(m,f)=>`${cap(f(m[1]))} is too large. Check the number and its unit.`],];const cap=(s)=>s.charAt(0).toUpperCase()+s.slice(1);export function noticeCode(out){const above=Object.keys(out).filter((k)=>k.endsWith('above_standard_sizes')&&out[k]===true);if(above.length)return above.every((k)=>k==='generator_above_standard_sizes'||'recommended_kva' in out)?'generator_above_standard_sizes':'above_standard_sizes';if(out.solar_above_sanctioned===true)return 'solar_above_sanctioned';if(out.low_confidence===true)return 'price_low_confidence';if(out.over_cable_rating===true)return 'cable_over_current_rating';if(out.ampacity_checked===false)return 'ampacity_not_checked_aluminium';if(out.protected_lost===true)return 'ac_protected_lost';if(out.ac_above_sanctioned===true)return 'ac_above_sanctioned';return '';}
export function errorMessage(code,labels={},choices=[]){if(EXACT[code])return EXACT[code];const r=/^load_(\d+)_(?:length_(?=r))?(.+)$/.exec(code);if(r&&EXACT[r[2]])return row(r)+EXACT[r[2]];const f=(key)=>labels[key]||key.replace(/_/g,' ');for(const[re,make]of PATTERNS){const m=code.match(re);if(m)return make(m,f,choices);}
return 'Something went wrong with this calculation. Please check your inputs.';}
